using Hexa.NET.ImGui;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;
using StudioCore.Application;
using StudioCore.Editors.Common;
using StudioCore.Editors.Viewport;
using StudioCore.Renderer;
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace StudioCore.Editors.ModelEditor;

/// <summary>
/// A game's snapshot set: the models to capture and how. Generated by Tools/RenderSnapshotDiff's pick mode into
/// Assets/Snapshots/{GAME}.json.
/// </summary>
public class RenderSnapshotSet
{
    public string Game { get; set; } = "";
    public int Width { get; set; } = 768;
    public int Height { get; set; } = 768;

    /// <summary>Degrees about the up axis; 0 looks along +Z</summary>
    public float Yaw { get; set; } = 35f;

    /// <summary>Degrees below the horizon the camera looks</summary>
    public float Pitch { get; set; } = 20f;

    public float Fov { get; set; } = 60f;

    /// <summary>The material clock while capturing: UV scroll and wind are drawn at this second</summary>
    public float Time { get; set; } = 0f;

    public List<RenderSnapshotEntry> Models { get; set; } = new();
}

public class RenderSnapshotEntry
{
    /// <summary>The model list's name for the container (the file dictionary's Filename)</summary>
    public string Container { get; set; } = "";

    /// <summary>The FLVER inside it; the container's first when empty</summary>
    public string Model { get; set; }

    /// <summary>What the model is there to show, for whoever reads a diff</summary>
    public string Shows { get; set; }

    public float? Yaw { get; set; }
    public float? Pitch { get; set; }

    [JsonIgnore]
    public string ImageName => string.IsNullOrEmpty(Model) || Model.Equals(Container, StringComparison.OrdinalIgnoreCase)
        ? $"{Container}.png"
        : $"{Container}__{Model}.png";
}

/// <summary>
/// Render Snapshots: loads each model of the game's snapshot set in turn, frames it from a fixed angle at a fixed
/// size, waits for its resources and the auto exposure to settle, and saves the tone mapped scene as a PNG. A run is
/// compared with a baseline by Tools/RenderSnapshotDiff. Plan: Documentation/Shader Family Split Plan.md, S1.
/// </summary>
public class ModelRenderSnapshotTool
{
    private enum Stage { Idle, Loading, Settling, Capturing }

    // Frames with no resource job or load session running before a model counts as loaded
    private const int IdleFramesToLoad = 30;

    // Frames after framing before the capture, for the exposure and the shadows to follow the camera
    private const int SettleFrames = 20;

    // The exposure counts as settled within this many stops of its target
    private const float ExposureTolerance = 0.02f;

    private static readonly TimeSpan LoadTimeout = TimeSpan.FromSeconds(120);
    private static readonly TimeSpan SettleTimeout = TimeSpan.FromSeconds(20);
    private static readonly TimeSpan CaptureTimeout = TimeSpan.FromSeconds(10);

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull
    };

    private readonly ModelEditorView View;
    private readonly ProjectEntry Project;

    // The set, read when the tool is first shown and again on each run
    private RenderSnapshotSet Set;
    private string SetError;
    private bool SetRead;

    // The run
    private Stage CurrentStage = Stage.Idle;
    private RenderSnapshotSet RunSet;
    private string RunFolder;
    private int EntryIndex;
    private ModelWrapper Target;
    private int IdleFrames;
    private int SettledFrames;
    private Stopwatch StageTime = new();
    private SnapshotPixels Pixels;
    private bool PixelsArrived;
    private DateTime RunStart;
    private readonly List<SnapshotResult> Results = new();

    // Settings changed for the run, put back after it
    private bool SavedTaa;
    private float SavedFov;

    private string Status = "";

    private sealed record SnapshotResult(string Container, string Model, string Image, string Outcome, bool Dirty);

    public ModelRenderSnapshotTool(ModelEditorView view, ProjectEntry project)
    {
        View = view;
        Project = project;
    }

    private string GameName => Project.Descriptor.ProjectType.ToString();

    private string SetPath => Path.Join(AppContext.BaseDirectory, "Assets", "Snapshots", $"{GameName}.json");

    public bool IsRunning => CurrentStage != Stage.Idle;

    /// <summary>Advances a run. Called every frame by the view, whether the tool is shown or not.</summary>
    public void Update()
    {
        if (CurrentStage == Stage.Idle)
            return;

        if (View.ViewportWindow?.Viewport is not VulkanViewport viewport)
        {
            Finish(LOC.Get("MODEL_RenderSnapshot_Status_No_Viewport"));
            return;
        }

        switch (CurrentStage)
        {
            case Stage.Loading:
                UpdateLoading(viewport);
                break;
            case Stage.Settling:
                UpdateSettling(viewport);
                break;
            case Stage.Capturing:
                UpdateCapturing(viewport);
                break;
        }
    }

    public void OnToolWindow()
    {
        if (!ToolSections.Header($"{LOC.Get("MODEL_RenderSnapshot_Header")}##modelRenderSnapshotHeader"))
            return;

        ImGui.BeginChild("ModelRenderSnapshotSection", ImGuiChildFlags.Borders);

        Display();

        ImGui.EndChild();
    }

    private void Display()
    {
        GUI.WrappedText(LOC.Get("MODEL_RenderSnapshot_Hint"));

        if (!SetRead)
        {
            ReadSet();
        }

        // Snapshot Set
        GUI.Spacer();
        GUI.SimpleHeader(LOC.Get("MODEL_RenderSnapshot_Set_Header"), LOC.Get("MODEL_RenderSnapshot_Set_Header_TT"));

        if (Set == null)
        {
            GUI.WrappedText(SetError ?? LOC.Get("MODEL_RenderSnapshot_Set_Missing", GameName, SetPath));
        }
        else
        {
            GUI.WrappedText(LOC.Get("MODEL_RenderSnapshot_Set_Summary", Set.Models.Count, Set.Width, Set.Height,
                Set.Yaw, Set.Pitch));
        }

        GUI.MultiButtonInput("modelRenderSnapshotSetActions",
            "modelRenderSnapshotReload", LOC.Get("MODEL_RenderSnapshot_Reload_Set"),
            LOC.Get("MODEL_RenderSnapshot_Reload_Set_TT"), ReadSet);

        // Output Folder
        GUI.Spacer();
        GUI.SimpleHeader(LOC.Get("MODEL_RenderSnapshot_Folder_Header"), LOC.Get("MODEL_RenderSnapshot_Folder_Header_TT"));

        ImGui.SetNextItemWidth(-1);
        ImGui.InputText("##modelRenderSnapshotFolder", ref CFG.Current.ModelEditor_RenderSnapshot_Folder, 512);
        GUI.Tooltip(LOC.Get("MODEL_RenderSnapshot_Folder_Input_TT"));

        // Actions
        GUI.Spacer();
        GUI.SimpleHeader(LOC.Get("MODEL_RenderSnapshot_Actions_Header"), LOC.Get("MODEL_RenderSnapshot_Actions_Header_TT"));

        var reason = GetBlockReason();

        if (reason != null && !IsRunning)
        {
            GUI.WrappedText(reason);
        }

        GUI.ConditionalMultiButtonInput("modelRenderSnapshotActions",
            "modelRenderSnapshotCapture", LOC.Get("MODEL_RenderSnapshot_Capture"),
            LOC.Get("MODEL_RenderSnapshot_Capture_TT"), Begin, reason == null && !IsRunning,

            "modelRenderSnapshotCancel", LOC.Get("MODEL_RenderSnapshot_Cancel"),
            LOC.Get("MODEL_RenderSnapshot_Cancel_TT"), () => Finish(LOC.Get("MODEL_RenderSnapshot_Status_Cancelled")),
            IsRunning);

        // Progress
        if (IsRunning || Results.Count > 0)
        {
            GUI.Spacer();
            GUI.SimpleHeader(LOC.Get("MODEL_RenderSnapshot_Progress_Header"), LOC.Get("MODEL_RenderSnapshot_Progress_Header_TT"));

            var total = Math.Max(RunSet?.Models.Count ?? 1, 1);
            var done = IsRunning ? EntryIndex : total;
            ImGui.ProgressBar(done / (float)total, new Vector2(-1, 0), $"{done} / {total}");

            GUI.WrappedText(Status);

            foreach (var failed in Results.Where(r => r.Outcome != "ok"))
            {
                GUI.WrappedTextColored(UI.Current.ImGui_Warning_Text_Color,
                    LOC.Get("MODEL_RenderSnapshot_Failed_Entry", failed.Container, failed.Outcome));
            }
        }
    }

    /// <summary>Why a run can't start now, or null</summary>
    private string GetBlockReason()
    {
        if (Set == null || Set.Models.Count == 0)
            return LOC.Get("MODEL_RenderSnapshot_Block_No_Set");

        if (string.IsNullOrWhiteSpace(CFG.Current.ModelEditor_RenderSnapshot_Folder))
            return LOC.Get("MODEL_RenderSnapshot_Block_No_Folder");

        if (!RenderMode.IsGame)
            return LOC.Get("MODEL_RenderSnapshot_Block_Not_Game_Mode");

        if (View.ViewportWindow?.Viewport is not VulkanViewport)
            return LOC.Get("MODEL_RenderSnapshot_Block_No_Viewport");

        return null;
    }

    private void ReadSet()
    {
        SetRead = true;
        Set = null;
        SetError = null;

        if (!File.Exists(SetPath))
            return;

        try
        {
            Set = JsonSerializer.Deserialize<RenderSnapshotSet>(File.ReadAllText(SetPath), JsonOptions);
        }
        catch (Exception e)
        {
            SetError = LOC.Get("MODEL_RenderSnapshot_Set_Unreadable", SetPath, e.Message);
        }
    }

    private void Begin()
    {
        ReadSet();

        if (GetBlockReason() is { } reason)
        {
            Status = reason;
            return;
        }

        var viewport = (VulkanViewport)View.ViewportWindow.Viewport;

        RunSet = Set;

        var gameFolder = Path.Join(CFG.Current.ModelEditor_RenderSnapshot_Folder, GameName);
        RunFolder = Path.Join(gameFolder, "Current");

        try
        {
            KeepPreviousRun(gameFolder);
            Directory.CreateDirectory(RunFolder);
        }
        catch (Exception e)
        {
            Status = LOC.Get("MODEL_RenderSnapshot_Status_Folder_Failed", RunFolder, e.Message);
            return;
        }

        Results.Clear();
        RunStart = DateTime.Now;

        // TAA's history and jitter differ frame to frame, so the run is drawn without it; FXAA stays as the GPARAM asks
        SavedTaa = CFG.Current.Viewport_Post_Taa;
        SavedFov = CFG.Current.Viewport_Camera_FOV;
        CFG.Current.Viewport_Post_Taa = false;
        CFG.Current.Viewport_Camera_FOV = RunSet.Fov;

        MaterialClock.FixedTime = RunSet.Time;
        viewport.CaptureSize = (RunSet.Width, RunSet.Height);

        EntryIndex = 0;
        StartEntry(viewport);
    }

    /// <summary>
    /// Moves the last run to Previous, so two runs can be compared without accepting either as the baseline. An
    /// older Previous goes to the snapshot folder's .archive.
    /// </summary>
    private static void KeepPreviousRun(string gameFolder)
    {
        var current = Path.Join(gameFolder, "Current");
        var previous = Path.Join(gameFolder, "Previous");

        if (!Directory.Exists(current))
            return;

        if (Directory.Exists(previous))
        {
            var game = Path.GetFileName(gameFolder);
            var archive = Path.Join(Path.GetDirectoryName(gameFolder), ".archive", game,
                $"Previous_{DateTime.Now:yyyyMMdd_HHmmss}");

            Directory.CreateDirectory(Path.GetDirectoryName(archive));
            Directory.Move(previous, archive);
        }

        Directory.Move(current, previous);
    }

    private void StartEntry(VulkanViewport viewport)
    {
        while (EntryIndex < RunSet.Models.Count)
        {
            var entry = RunSet.Models[EntryIndex];
            Status = LOC.Get("MODEL_RenderSnapshot_Status_Loading", entry.Container, EntryIndex + 1, RunSet.Models.Count);

            var outcome = LoadEntry(entry);

            if (outcome == null)
            {
                CurrentStage = Stage.Loading;
                IdleFrames = 0;
                StageTime.Restart();
                return;
            }

            Record(entry, null, outcome);
            EntryIndex++;
        }

        Finish(null);
    }

    /// <summary>Starts loading the entry's model. Returns why it couldn't, or null.</summary>
    private string LoadEntry(RenderSnapshotEntry entry)
    {
        var bank = Project.Handler.ModelData.PrimaryBank;
        var container = bank.Models.FirstOrDefault(e =>
            e.Key.Filename.Equals(entry.Container, StringComparison.OrdinalIgnoreCase)).Value;

        if (container == null)
            return "container not found";

        container.PopulateModelList();

        var model = string.IsNullOrEmpty(entry.Model)
            ? container.Models.FirstOrDefault()
            : container.Models.FirstOrDefault(m => m.Name.Equals(entry.Model, StringComparison.OrdinalIgnoreCase));

        if (model == null)
            return "model not found in container";

        View.Selection.SelectedModelContainerWrapper = container;

        if (!View.LoadModel(model))
            return "model open in another view";

        Target = model;
        return null;
    }

    private static bool ResourcesIdle =>
        ResourceManager.ActiveJobProgress.IsEmpty && !ResourceLoadTracker.HasActiveSession;

    private void UpdateLoading(VulkanViewport viewport)
    {
        var entry = RunSet.Models[EntryIndex];

        if (StageTime.Elapsed > LoadTimeout)
        {
            NextEntry(viewport, entry, "load timed out");
            return;
        }

        var container = Target?.Container;

        if (View.Selection.SelectedModelWrapper != Target || container == null ||
            !container.TryGetMeshBounds(out var bounds))
        {
            IdleFrames = 0;
            return;
        }

        IdleFrames = ResourcesIdle ? IdleFrames + 1 : 0;

        if (IdleFrames < IdleFramesToLoad)
            return;

        // The view direction first, as FitBox keeps the camera's direction
        var yaw = (entry.Yaw ?? RunSet.Yaw) * MathF.PI / 180f;
        var pitch = (entry.Pitch ?? RunSet.Pitch) * MathF.PI / 180f;

        // A positive X turns the camera down (the first DES captures, taken with -pitch, looked up at the models)
        viewport.ViewportCamera.CameraTransform.EulerRotation = new Vector3(pitch, yaw, 0f);
        viewport.FitBox(bounds);

        // Selected objects are drawn highlighted
        View.ViewportSelection.ClearSelection();

        CurrentStage = Stage.Settling;
        SettledFrames = 0;
        StageTime.Restart();
        Status = LOC.Get("MODEL_RenderSnapshot_Status_Settling", entry.Container, EntryIndex + 1, RunSet.Models.Count);
    }

    private void UpdateSettling(VulkanViewport viewport)
    {
        // Textures can still arrive after the meshes; each one starts the count again
        SettledFrames = ResourcesIdle ? SettledFrames + 1 : 0;

        var timedOut = StageTime.Elapsed > SettleTimeout;

        if (!timedOut && (SettledFrames < SettleFrames || !ExposureSettled(viewport)))
            return;

        Pixels = null;
        PixelsArrived = false;

        viewport.Snapshot.Request(pixels =>
        {
            Pixels = pixels;
            PixelsArrived = true;
        });

        CurrentStage = Stage.Capturing;
        StageTime.Restart();
    }

    private static bool ExposureSettled(VulkanViewport viewport)
    {
        var exposure = viewport.ViewPipeline.AutoExposure;

        if (!exposure.Applied)
            return true;

        var state = exposure.LastState;
        return state.Valid > 0 && MathF.Abs(state.Ev - state.TargetEv) < ExposureTolerance;
    }

    private void UpdateCapturing(VulkanViewport viewport)
    {
        var entry = RunSet.Models[EntryIndex];

        if (!PixelsArrived)
        {
            // The snapshot is only drawn while the viewport is on screen
            if (StageTime.Elapsed > CaptureTimeout)
            {
                viewport.Snapshot.Cancel();
                NextEntry(viewport, entry, "viewport not visible");
            }

            return;
        }

        if (Pixels == null)
        {
            NextEntry(viewport, entry, "readback failed");
            return;
        }

        try
        {
            // The tone map leaves alpha as it comes, which isn't part of the look
            var rgba = Pixels.Rgba;
            for (var i = 3; i < rgba.Length; i += 4)
            {
                rgba[i] = 255;
            }

            using var image = SixLabors.ImageSharp.Image.LoadPixelData<Rgba32>(rgba, Pixels.Width, Pixels.Height);
            image.SaveAsPng(Path.Join(RunFolder, entry.ImageName));

            NextEntry(viewport, entry, "ok");
        }
        catch (Exception e)
        {
            NextEntry(viewport, entry, $"save failed: {e.Message}");
        }
    }

    private void NextEntry(VulkanViewport viewport, RenderSnapshotEntry entry, string outcome)
    {
        Record(entry, Target, outcome);

        Target = null;
        EntryIndex++;
        StartEntry(viewport);
    }

    private void Record(RenderSnapshotEntry entry, ModelWrapper model, string outcome)
    {
        Results.Add(new SnapshotResult(entry.Container, model?.Name ?? entry.Model, entry.ImageName, outcome,
            model?.IsDirty ?? false));

        if (outcome != "ok")
        {
            Smithbox.Log(GetType(), $"Render snapshot of {entry.Container}: {outcome}", Microsoft.Extensions.Logging.LogLevel.Warning);
        }
    }

    /// <summary>Ends the run, puts the settings back and writes the manifest. A null status means it completed.</summary>
    private void Finish(string status)
    {
        if (CurrentStage == Stage.Idle)
            return;

        CurrentStage = Stage.Idle;

        if (View.ViewportWindow?.Viewport is VulkanViewport viewport)
        {
            viewport.CaptureSize = null;
            viewport.Snapshot.Cancel();
        }

        CFG.Current.Viewport_Post_Taa = SavedTaa;
        CFG.Current.Viewport_Camera_FOV = SavedFov;
        MaterialClock.FixedTime = null;

        var ok = Results.Count(r => r.Outcome == "ok");
        Status = status ?? LOC.Get("MODEL_RenderSnapshot_Status_Done", ok, Results.Count, RunFolder);

        WriteManifest(status == null);
    }

    private void WriteManifest(bool complete)
    {
        try
        {
            var manifest = new
            {
                Game = GameName,
                Started = RunStart.ToString("s"),
                Finished = DateTime.Now.ToString("s"),
                Complete = complete,
                SmithboxVersion = typeof(ModelRenderSnapshotTool).Assembly.GetName().Version?.ToString(),
                RunSet.Width,
                RunSet.Height,
                RunSet.Yaw,
                RunSet.Pitch,
                RunSet.Fov,
                RunSet.Time,
                Settings = new Dictionary<string, object>
                {
                    ["RenderMode"] = RenderMode.Current.ToString(),
                    ["Texturing"] = RenderMode.Texturing.ToString(),
                    ["PostEffects"] = CFG.Current.Viewport_Post_Effects,
                    ["AutoExposure"] = CFG.Current.Viewport_Post_Auto_Exposure,
                    ["Bloom"] = CFG.Current.Viewport_Post_Bloom,
                    ["Glow"] = CFG.Current.Viewport_Post_Glow,
                    ["Fxaa"] = CFG.Current.Viewport_Post_Fxaa,
                    ["Ssao"] = CFG.Current.Viewport_Post_Ssao,
                    ["Ssr"] = CFG.Current.Viewport_Post_Ssr,
                    ["ColorGrading"] = CFG.Current.Viewport_Post_Color_Grading,
                    ["ToneCorrection"] = CFG.Current.Viewport_Post_Tone_Correction,
                    ["MaterialAnimation"] = CFG.Current.Viewport_Enable_Material_Animation
                },
                Results = Results.Select(r => new { r.Container, r.Model, r.Image, r.Outcome, r.Dirty }).ToList()
            };

            File.WriteAllText(Path.Join(RunFolder, "manifest.json"), JsonSerializer.Serialize(manifest, JsonOptions));
        }
        catch (Exception e)
        {
            Smithbox.LogError(GetType(), $"Failed to write the render snapshot manifest in {RunFolder}", e);
        }
    }
}
